'use strict';

/**
* Round each component of a single-precision complex floating-point number toward positive infinity.
*
* @module @stdlib/math-base-special-cceilf
*
* @example
* import Complex64 from '@stdlib/complex-float32-ctor';
* import cceilf from '@stdlib/math-base-special-cceilf';
*
* var v = cceilf( new Complex64( -1.5, 2.5 ) );
* // returns <Complex64>[ -1.0, 3.0 ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import assign from './assign.js';
import strided from './strided.js';


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'strided', strided );


// EXPORTS //

export default main;

// exports: { "assign": "main.assign", "strided": "main.strided" }
